const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // Helper to await getInfo
    const getInfo = (obj) => new Promise((resolve, reject) => obj.getInfo(resolve, reject));

    // 1. Geometry & Time Definitions
    // Mount Vesuvius cone vicinity (approx crater) with 1500 m buffer to ensure counts at 1000 m scale
    const roi = ee.Geometry.Point([14.4265, 40.8214]).buffer(1500);
    const start = '2022-01-02';
    const end = '2022-01-03'; // exclusive

    // 2. Collections and availability checks
    const l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterBounds(roi).filterDate(start, end);
    const l8Count = await getInfo(l8.size());
    console.log(`Landsat 8 images on 2022-01-02: ${l8Count}`);

    if (l8Count === 0) {
      // Try fallback per instructions (do not use for final A/B, only to diagnose C1)
      const l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterBounds(roi).filterDate(start, end);
      const l9Count = await getInfo(l9.size());
      console.log(`Landsat 9 images on 2022-01-02 (fallback info): ${l9Count}`);
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      return;
    }

    // 3. Cloud masking for L8 C2 L2
    function maskL8(img) {
      const qa = img.select('QA_PIXEL');
      const mask = qa.bitwiseAnd(1 << 0).eq(0) // no fill
        .and(qa.bitwiseAnd(1 << 1).eq(0))     // no dilated cloud
        .and(qa.bitwiseAnd(1 << 2).eq(0))     // no cirrus
        .and(qa.bitwiseAnd(1 << 3).eq(0))     // no cloud
        .and(qa.bitwiseAnd(1 << 4).eq(0))     // no cloud shadow
        .and(qa.bitwiseAnd(1 << 5).eq(0));    // no snow
      return img.updateMask(mask);
    }

    // 4. Per-image ROI stats (counts at 1000 m for performance)
    const withStats = l8.map(function(img) {
      const masked = maskL8(img);
      const total = ee.Number(img.select('SR_B2').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: 1000,
        maxPixels: 1e9
      }).get('SR_B2'));
      const valid = ee.Number(masked.select('SR_B2').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: 1000,
        maxPixels: 1e9
      }).get('SR_B2'));
      const frac = ee.Algorithms.If(total.gt(0), valid.divide(total), ee.Number(0));
      return img.set({totalCount: total, validCount: valid, cloudFreeFrac: frac});
    });

    const best = ee.Image(withStats.sort('cloudFreeFrac', false).first());
    const totalCount = await getInfo(best.get('totalCount'));
    const validCount = await getInfo(best.get('validCount'));
    const frac = await getInfo(best.get('cloudFreeFrac'));
    const prodId = await getInfo(best.get('LANDSAT_PRODUCT_ID'));
    const dateStr = await getInfo(ee.Date(best.get('system:time_start')).format('YYYY-MM-dd'));

    // 5. Validation and outputs
    console.log(`Best image: ${prodId || 'unknown'} on ${dateStr}`);
    console.log(`Total pixels (1000 m scale): ${totalCount || 0}`);
    console.log(`Valid pixels after cloud/snow mask: ${validCount || 0}`);
    if (totalCount === null || validCount === null || frac === null || isNaN(frac)) {
      console.log('C3: Calculation Failure (Result is None, NaN, or invalid).');
      return;
    }
    if (totalCount === 0) {
      // Image exists but ROI not covered at sampling scale; treat as no valid pixels for this ROI
      console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).');
      return;
    }
    const cloudFreePct = (frac * 100);
    const cloudPct = (100 - cloudFreePct);
    console.log(`Cloud-free fraction over ROI: ${cloudFreePct.toFixed(1)}%`);
    console.log(`Cloud (or masked) fraction over ROI: ${cloudPct.toFixed(1)}%`);

    // Decision: visible if ≥50% of ROI cloud-free
    if (validCount === 0) {
      console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).');
      return;
    }
    if (frac >= 0.5) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
